import type { IPlatformService, TelemetryRendererContext } from "@lcode/shared";

/**
 * preload 只暴露现有平台操作；签名统一取自 shared，避免声明与 IPC 实现各自演进。
 * Required 表示当前 Renderer 直接调用的基础能力；Partial 保留旧 preload 的能力检测边界。
 */
export type DesktopPreloadBridge = Required<
  Pick<
    IPlatformService,
    | "connectRemote"
    | "disposeRemoteSession"
    | "isDockerAvailable"
    | "listWSLDistros"
    | "listDockerContainers"
    | "listSSHConfigAliases"
    | "loadMcpFromUserDirectory"
    | "saveMcpToUserDirectory"
    | "migrateLegacyCommonMcp"
    | "selectDirectory"
    | "selectFile"
    | "searchWallpaperMarket"
    | "loadWallpaperMarketImage"
    | "createTempTextAttachment"
    | "onRemoteConnectionLog"
    | "onRemoteSessionClosed"
    | "syncWindowTabs"
    | "syncWindowUnreadCount"
    | "syncActiveTaskSession"
    | "onFocusTab"
    | "onNewTab"
    | "onNewTask"
    | "onWindowFullscreenChanged"
    | "onTaskNotificationClick"
    | "openExternal"
    | "canOpenCommunity"
    | "openInFileManager"
    | "openExternalFile"
    | "registerOAuthState"
    | "onOAuthCallback"
    | "onPaymentCallback"
    | "notifyRendererReady"
    | "reportTelemetryEvent"
    | "reportArmsCustomEvent"
    | "reportLocalTtftBatch"
    | "showTaskNotification"
    | "exportLogs"
    | "onUpdateCheckResult"
    | "onUpdateReady"
    | "onPostUpdateReleaseNotes"
    | "acknowledgePostUpdateReleaseNotes"
    | "quitAndInstallUpdate"
    | "getInstalledEditors"
    | "openInEditor"
    | "executeDesktopCommand"
    | "setApplicationLocale"
    | "setTitleBarTheme"
  >
> &
  Partial<
    Pick<
      IPlatformService,
      | "cancelPendingRemoteConnection"
      | "bindRemoteWorkspaceSessionContext"
      | "startRemotePairing"
      | "stopRemotePairing"
      | "decideRemotePairing"
      | "onRemotePairingState"
      | "listRemoteDevices"
      | "revokeRemoteDevice"
      | "getRemoteControlConfig"
      | "setRemoteControlConfig"
      | "testRemoteControlConnection"
      | "selectDirectories"
      | "selectFiles"
      | "saveFile"
      | "printPageToPdf"
      | "getPathForFile"
      | "activateOrSetWorkspace"
      | "syncAppSettings"
      | "setShortcutRecordingActive"
      | "onCloseActiveContextRequest"
      | "onOpenBrowserUrl"
      | "onBrowserViewReady"
      | "onBrowserViewOperation"
      | "onBrowserViewViewportChanged"
      | "onBrowserViewScreenshotSurfacePrepare"
      | "onBrowserViewScreenshotSurfaceRelease"
      | "browserViewScreenshotSurfaceReady"
      | "onBrowserViewVisibility"
      | "onBrowserViewCloseTab"
      | "onBrowserViewSuspend"
      | "onBrowserViewRestore"
      | "onOpenWorkspace"
      | "onOpenWorkspacePath"
      | "onOpenFeedbackDialog"
      | "onOpenTicketsPanel"
      | "getDesktopWindowChromeState"
      | "onDesktopWindowChromeStateChanged"
      | "getWindowControlsOverlayMetrics"
      | "onWindowControlsOverlayChanged"
      | "getDesktopZoomLevel"
      | "onDesktopZoomLevelChanged"
      | "openCuaPermissionOnboarding"
      | "cancelCuaPermissionOnboarding"
      | "prepareCuaHelperPermissionDrag"
      | "startCuaHelperPermissionDrag"
      | "onShareImport"
      | "getRendererActionTraceConfig"
      | "onRendererActionTraceConfigChanged"
      | "reportRendererActionTraceBatch"
      | "reportRendererHeapSample"
      | "captureWindowScreenshot"
      | "browserViewAttachGuest"
      | "browserViewDetachGuest"
      | "browserViewCloseTab"
      | "browserViewReportResidency"
      | "browserViewSuspendReady"
      | "browserViewEnsureResident"
      | "browserViewRestoreTabs"
      | "browserViewUpdateViewport"
      | "importChromeBrowserData"
      | "clearEmbeddedBrowserData"
      | "getLCodeStdioTapDevState"
      | "onSettingsChanged"
      | "onApplicationLocaleChanged"
      | "getUpdateState"
      | "downloadUpdate"
      | "cancelUpdateDownload"
      | "openUpdateStatusWindow"
      | "getAutoUpdatePreferences"
      | "setAutoDownloadAndInstallUpdates"
      | "getDesktopSessionActivity"
      | "onUpdateStateChanged"
      | "skipUpdateVersion"
      | "getApplicationIcon"
      | "getSystemLocale"
      | "getSystemUsername"
    >
  > & {
    /** renderer 日志交由 Main 统一落盘；不作为 UI 业务接口。 */
    log(level: "info" | "warn" | "error", args: unknown[]): void;
    syncTelemetryContext(context: TelemetryRendererContext): void;
    // 平台读取同步启动快照；此原生 IPC 查询仍是异步，不能与同步签名混为一谈。
    getDeviceId(): Promise<ReturnType<IPlatformService["getDeviceId"]>>;
  };

declare global {
  interface Window {
    lcode: DesktopPreloadBridge;
  }
}
